function render(){if(!D)return;if(!visible(page))page='dashboard';$('nav').innerHTML=menus.filter(x=>visible(x[0])).map(([id,icon,n])=>`<button class="${page===id?'active':''}" data-action="nav" data-id="${id}"><span>${icon}</span>${n}</button>`).join('');$('title').textContent=menus.find(x=>x[0]===page)[2];document.title=$('title').textContent+' | Sapori Rumeni Manager';const f={dashboard,orders:ordersPage,products:productRows,calendar,production,shipping:()=>ordersPage('shipping'),payments,customers,records,reports,notifications,settings:settingsPage,team,coupons:couponPage,reviews:reviewPage,audit:auditPage};$('content').innerHTML=f[page]();if($('search'))$('search').oninput=e=>{filter=e.target.value;let pos=e.target.selectionStart;render();$('search').focus();$('search').setSelectionRange(pos,pos)};if($('production-date'))$('production-date').onchange=e=>{productionDate=e.target.value;render()};if($('report-period'))$('report-period').onchange=e=>{reportPeriod=e.target.value;render()};if($('statefilter'))$('statefilter').onchange=e=>{statusFilter=e.target.value;render()};if($('settingsform'))$('settingsform').onsubmit=async e=>{e.preventDefault();const f=e.target,x=Object.fromEntries(new FormData(f));for(const k of ['open','shipping','bankEnabled','catalogReviewed','shippingReviewed','maintenance'])x[k]=f.elements[k].checked;for(const k of ['min','fee','free','lead','capacity'])x[k]=Number(x[k]);for(const k of ['times','closedDates','closedDays','allowedCaps','dispatchDays'])x[k]=x[k].split(',').map(x=>x.trim()).filter(Boolean);x.closedDays=x.closedDays.map(Number);x.dispatchDays=x.dispatchDays.map(Number);x.featured=x.featured.split(',').map(x=>x.trim()).filter(x=>/^\d+$/.test(x)).map(Number).slice(0,12);await mutate('settings',x)} }
function romeLocal(v){if(!v)return '';const p=Object.fromEntries(new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(v)).map(x=>[x.type,x.value]));return p.year+'-'+p.month+'-'+p.day+'T'+p.hour+':'+p.minute}function romeUTC(v){if(!v)return '';let a=Date.parse(v+':00Z');if(!Number.isFinite(a))throw Error('Data non valida');let target=a;for(let i=0;i<3;i++)a+=target-Date.parse(romeLocal(new Date(a))+':00Z');if(romeLocal(new Date(a))!==v)throw Error('Orario non valido');return new Date(a).toISOString()}
function field(n,l,v='',type='text',attrs=''){return `<label>${esc(l)}<input name="${n}" type="${type}" value="${esc(v)}" ${attrs}></label>`}function area(n,l,v=''){return `<label class="full">${esc(l)}<textarea name="${n}">${esc(v)}</textarea></label>`}function select(n,l,v,opts){return `<label>${esc(l)}<select name="${n}">${opts.map(([k,t])=>`<option value="${esc(k)}" ${String(k)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function modal(title,html,save){$('modaltitle').textContent=title;$('modalbody').innerHTML=html;modalSave=save;$('save').disabled=false;$('save').hidden=!save;if(!$('modal').open)$('modal').showModal()}
$('close').onclick=$('cancel').onclick=()=>{if(!$('save').disabled)$('modal').close()};$('modal').addEventListener('cancel',e=>{if($('save').disabled)e.preventDefault()});$('modalform').onsubmit=async e=>{e.preventDefault();if(!modalSave)return;let b=$('save');b.disabled=true;try{await modalSave(e.target,Object.fromEntries(new FormData(e.target)));$('modal').close();try{await refresh();notice('Modifica salvata')}catch(e){notice('Modifica salvata; aggiornamento dei dati non riuscito. Premi Aggiorna.',true)}}catch(err){notice(err.message,true);let el=$('modalbody').querySelector('.formerror');if(!el){el=document.createElement('p');el.className='formerror danger';$('modalbody').prepend(el)}el.textContent=err.message}finally{b.disabled=false}};
