function editOrder(id){delete $('modalform').dataset.lastOperation;delete $('modalform').dataset.operationId;let o=order(id);let opts=[o.status,...(trans[o.status]||[])].filter(s=>!(s==='Spedita'&&o.method==='pickup')&&!(s==='Pronta'&&o.method==='scheduled'));if(!manager()){opts=opts.filter(s=>s===o.status||['In preparazione','Pronta'].includes(s));modal(o.id,`<div class="stack">${table(['Prodotto','Quantità'],o.lines.map(l=>[esc(l.it),qty(l.qty)+' '+esc(l.unit)]))}${select('status','Stato',o.status,opts.map(x=>[x,x]))}</div>`,async(f,x)=>{if(x.status!==o.status)await api('order/prepare',{id,status:x.status})});return}
let canLines=active(o)&&o.status!=='Spedita'&&!o.paid&&!o.coupon;let closed=!active(o)||o.status==='Spedita';modal(o.id,`<div class="stack"><div><strong>${esc(o.name)}</strong><p>${esc(o.email)} · ${esc(o.phone)}</p><p>${esc(o.address||o.day+' '+o.time)}</p><small>Note cliente: ${esc(o.notes)}</small></div><div id="lines" class="stack">${o.lines.map(l=>lineHtml(l,canLines)).join('')}</div>${canLines?'<button type="button" id="addline">+ Prodotto</button>':''}<div class="fields">${select('status','Stato operativo',o.status,opts.map(x=>[x,x]))}${field('assignee','Assegna a',o.assignee)}${o.method==='pickup'&&!closed?field('day','Giorno ritiro',o.day,'date')+field('time','Ora ritiro',o.time,'time'):''}${!closed?field('fee','Spedizione €',o.fee,'number','min="0" step=".01"')+field('final','Totale definitivo €',o.final??'','number','min="0" step=".01"'):''}${field('tracking','Tracking',o.tracking)}${area('internal','Note interne',o.internal)}${field('paymentAmount','Registra incasso verificato €','','number','min=".01" step=".01"')}${owner()?field('refundAmount','Registra rimborso già eseguito €','','number','min=".01" step=".01"'):''}</div><div class="banner">${o.coupon?'Codice '+esc(o.coupon)+' · Sconto '+eur(o.discount)+' · ':''}Stima ${eur(o.total)} · Incasso netto ${eur(net(o))} · Saldo ${eur(Math.max(0,due(o)-net(o)))}. La registrazione non sposta denaro.</div><button type="button" id="printOrder">Stampa riepilogo</button>${o.method==='scheduled'?'<button type="button" id="printLabel">Stampa etichetta interna</button>':''}<div><h3>Storico</h3>${o.history.map(x=>`<small>${esc(date(x.time))} · ${esc(x.actor)} · ${esc(x.action)}</small><br>`).join('')}</div></div>`,async(f,x)=>{let p={id,status:x.status,internal:x.internal,tracking:x.tracking,assignee:x.assignee};if(x.day)p.day=x.day;if(x.time)p.time=x.time;if(x.fee!==undefined&&Number(x.fee)!==o.fee)p.fee=Number(x.fee);if(x.final!==undefined&&x.final!==''&&Number(x.final)!==o.final)p.final=Number(x.final);if(canLines){let lines=readLines();if(JSON.stringify(lines)!==JSON.stringify(o.lines.map(l=>({id:l.id,qty:l.qty,price:l.price}))))p.lines=lines}if(x.paymentAmount)p.paymentAmount=Number(x.paymentAmount);if(x.refundAmount)p.refundAmount=Number(x.refundAmount);if(f.elements.sendPayment?.checked){p.sendPayment=true;p.paymentLink=x.paymentLink}const fingerprint=JSON.stringify(p);if(f.dataset.lastOperation!==fingerprint){f.dataset.lastOperation=fingerprint;f.dataset.operationId=crypto.randomUUID();}p.operationId=f.dataset.operationId;await api('order/update',p)});if($('addline'))$('addline').onclick=()=>{$('lines').insertAdjacentHTML('beforeend',lineHtml({id:D.products[0].id,qty:1,price:D.products[0].price},true));wireLines()};wireLines();$('printOrder').onclick=()=>window.print();if($('printLabel'))$('printLabel').onclick=()=>{const w=window.open('','_blank','width=650,height=500');if(!w){notice('Consenti le finestre di stampa',true);return}w.opener=null;w.document.write('<!doctype html><html lang="it"><meta charset="utf-8"><title>Etichetta interna</title><style>body{font:18px system-ui;padding:30px}h1{font:28px Georgia}main{border:1px solid #222;padding:20px;width:100mm}small{font-size:11px}</style><main><h1>Sapori Rumeni</h1><p>Preparazione refrigerata</p><h2>'+esc(o.name)+'</h2><p>'+esc(o.address)+'</p><p>'+esc(o.phone)+'</p><p>'+esc(o.id)+'</p><small>Etichetta interna: non sostituisce la lettera di vettura del corriere.</small></main></html>');w.document.close();w.focus();w.print()}}
function lineHtml(l,editable){if(!editable)return `<div class="listrow"><span>${esc(l.it)}</span><strong>${qty(l.qty)} ${esc(l.unit)} · ${eur(l.price*l.qty)}</strong></div>`;return `<div class="orderline">${select('pid','Prodotto',l.id,D.products.filter(p=>p.active&&!p.archived||p.id===l.id).map(p=>[p.id,p.it]))}${field('lqty','Quantità',l.qty,'number','required min=".001" step=".001"')}${field('lprice','Prezzo unitario',l.price,'number','required min="0" step=".01"')}<button type="button" class="removeLine">×</button></div>`}
function wireLines(){document.querySelectorAll('.removeLine').forEach(b=>b.onclick=()=>b.closest('.orderline').remove());document.querySelectorAll('.orderline select').forEach(s=>s.onchange=()=>s.closest('.orderline').querySelector('[name=lprice]').value=prod(s.value).price)}function readLines(){return [...document.querySelectorAll('#lines .orderline')].map(e=>({id:Number(e.querySelector('[name=pid]').value),qty:Number(e.querySelector('[name=lqty]').value),price:Number(e.querySelector('[name=lprice]').value)}))}
function manual(){delete $('modalform').dataset.requestId;modal('Nuovo ordine manuale',`<div class="fields">${field('name','Nome cliente','','text','required')}${field('email','Email','','email','required')}${field('phone','Telefono','','tel','required')}${select('lang','Lingua','it',[['it','Italiano'],['ro','Rumeno']])}${select('method','Modalità','pickup',[['pickup','Ritiro'],['scheduled','Spedizione']])}${select('payment','Pagamento','store',[['store','In negozio'],...(D.settings.bankEnabled?[['bank','Bonifico']]:[])])}${field('pickupDate','Giorno ritiro','','date')}${field('pickupTime','Orario ritiro','','time')}${field('address','Indirizzo spedizione')}${field('cap','CAP')}${field('city','Città')}${field('province','Provincia')}${area('notes','Note')}<label class="line full"><input type="checkbox" name="consent" required> Il cliente ha autorizzato la registrazione e comunicazione dei dati</label></div><div id="lines" class="stack">${lineHtml({id:D.products[0].id,qty:1,price:D.products[0].price},true)}</div><button type="button" id="addline">+ Prodotto</button>`,async(f,x)=>{x.requestId=f.dataset.requestId||(f.dataset.requestId=crypto.randomUUID());x.consent=f.elements.consent.checked;x.province=x.province.toUpperCase();let lines=readLines();if(new Set(lines.map(l=>l.id)).size!==lines.length)throw Error('Unisci prodotti duplicati');x.items=Object.fromEntries(lines.map(l=>[l.id,l.qty]));await api('order/manual',x)});$('addline').onclick=()=>{$('lines').insertAdjacentHTML('beforeend',lineHtml({id:D.products[0].id,qty:1,price:D.products[0].price},true));wireLines()};wireLines()}
function exportCSV(kind){let rows=kind==='orders'?[['ID','Data','Stato','Modalità','Ritiro','Totale','Incasso'],...D.orders.map(o=>[o.id,o.created,o.status,o.method,o.day+' '+o.time,due(o),net(o)])]:[['ID','Italiano','Rumeno','Scorta','Riservato','Disponibile',...(manager()?['Prezzo']:[])],...D.products.map(p=>[p.id,p.it,p.ro,p.stock,D.reserved[p.id]||0,available(p),...(manager()?[p.price]:[])])];const safe=v=>{let s=String(v??'');if(/^[\s\u0000-\u001f]*[=+@-]|^[\t\r\n]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};let u=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=u;a.download=kind+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function recordEdit(k,id){let r=D.records.find(x=>x.kind===k&&x.id===id)||{};modal(kinds[k],`<div class="fields">${field('title','Titolo',r.title,'text','required')}${field('date','Data / scadenza',r.date,'date')}${field('state','Stato',r.state)}${area('detail','Dettagli',r.detail)}</div>`,async(f,x)=>api('record',{kind:k,id,...x}))}
function downloadText(text,name,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function bulkEdit(){const rows=D.products.filter(p=>!p.archived);modal('Prezzi e scorte · modifica multipla',`<p>Modifica le righe desiderate; il salvataggio è unico. Le scorte non possono scendere sotto le quantità riservate.</p><div class="tablewrap"><table><thead><tr><th>Prodotto</th><th>Prezzo €</th><th>Scorta</th></tr></thead><tbody>${rows.map(p=>`<tr data-bulk="${p.id}"><td>${esc(p.it)}</td><td><input aria-label="Prezzo ${esc(p.it)}" type="number" min=".01" step=".01" name="bp" value="${p.price}"></td><td><input aria-label="Scorta ${esc(p.it)}" type="number" min="${D.reserved[p.id]||0}" step="${p.unit==='kg'?'.001':'1'}" name="bs" value="${p.stock}"></td></tr>`).join('')}</tbody></table></div>`,async f=>{let payload=[...f.querySelectorAll('[data-bulk]')].map(r=>{const p=prod(r.dataset.bulk);return {id:p.id,updated_at:p.updated_at,price:Number(r.querySelector('[name=bp]').value),stock:Number(r.querySelector('[name=bs]').value)}}).filter(r=>{const p=prod(r.id);return r.price!==p.price||r.stock!==p.stock});if(payload.length)await api('bulk',payload);});}
function importCSV(){modal('Importa prezzi e scorte',`<p>CSV Excel con intestazione <code>id;price;stock</code>. Solo prodotti esistenti; numeri con punto decimale, nessuna modifica finché non premi Salva.</p><label>File CSV<input type="file" id="csv-file" accept=".csv,text/csv"></label><button type="button" id="csv-template">Scarica modello</button><pre id="csv-preview"></pre>`,async()=>{const file=$('csv-file').files[0];if(!file||file.size>100000)throw Error('Scegli CSV valido, massimo 100 KB');const lines=(await file.text()).replace(/^\ufeff/,'').trim().split(/\r?\n/);if(lines.shift().trim().toLowerCase()!=='id;price;stock')throw Error('Intestazione non valida');const payload=lines.filter(Boolean).map(l=>{const c=l.split(';');if(c.length!==3||!c.every(v=>/^\d+(?:\.\d+)?$/.test(v.trim())))throw Error('Riga non valida: '+l);const p=prod(c[0]);if(!p||p.archived)throw Error('ID non valido: '+c[0]);return {id:p.id,updated_at:p.updated_at,price:Number(c[1]),stock:Number(c[2])}});if(!payload.length)throw Error('Nessuna riga');if(!confirm('Aggiornare '+payload.length+' prodotti?'))throw Error('Importazione annullata');await api('bulk',payload);});$('csv-template').onclick=()=>downloadText('id;price;stock\n'+D.products.filter(p=>!p.archived).map(p=>`${p.id};${p.price};${p.stock}`).join('\n'),'modello_prezzi_scorte.csv','text/csv');}
async function duplicateProduct(id){const p=prod(id);if(!p||p.archived)return;if(!confirm('Duplicare '+p.it+'? La copia sarà nascosta con scorta zero.'))return;await mutate('product',{...p,id:null,it:p.it+' (copia)',ro:p.ro+' (copie)',active:false,stock:0,barcode:'',updated_at:null});}
document.addEventListener('click',async e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=b.dataset.id;try{if(a==='nav')nav(id);else if(a==='order-filter'){nav('orders');statusFilter=id;render()}else if(a==='product')editProduct(id);else if(a==='stock')editProduct(id);else if(a==='photo')editProduct(id,true);else if(a==='bulk')bulkEdit();else if(a==='import')importCSV();else if(a==='duplicate')await duplicateProduct(id);else if(a==='archive'||a==='restore'){if(confirm(a==='archive'?'Spostare nel cestino?':'Ripristinare come prodotto nascosto?'))await mutate('archive',{id:Number(id),archive:a==='archive'});}else if(a==='coupon')couponEdit(id);else if(a==='moderate'){const r=D.reviews.find(x=>x.id===id);await mutate('review',{id,approved:!r.approved});}else if(a==='catalog-filter'){statusFilter=id;render();}else if(a==='order')editOrder(id);else if(a==='manual')manual();else if(a==='recipes59')recipesList59();else if(a==='recipe59')recipeEdit59(id);else if(a==='prepare59')prepareEdit59(id);else if(a==='move59')moveEdit59(id);else if(a==='history59')stockHistory59();else if(a==='customer59')customerDetail59(id);else if(a==='production-all'){productionDate='';render()}else if(a==='cal'){calendarOffset=id==='0'?0:calendarOffset+Number(id);render()}else if(a==='export')exportCSV(id);else if(a==='print')window.print();else if(a==='backup'){let r=await api('backup',{});notice(r.message+' · '+r.file)}else if(a==='user')modal('Abilita account staff esistente',`<p>Crea prima l’account con email e password in Supabase Authentication, poi abilitalo qui.</p><div class="fields">${field('name','Email staff','','email','required')}<label>Ruolo<input readonly value="Manager"></label></div>`,async(f,x)=>api('user',{name:x.name,role:'manager',active:true}));else if(a==='toggleuser'){let u=D.users.find(x=>x.name===id);if(confirm('Cambiare accesso di '+id+'?'))await mutate('user',{name:id,active:!u.active})}else if(a==='record')recordEdit(id);else if(a==='recordEdit')recordEdit(...id.split(':'));else if(a==='recordDelete'&&confirm('Eliminare questo registro?')){let [kind,rid]=id.split(':');await mutate('record',{kind,id:rid,delete:true})}}catch(err){notice(err.message,true)}});
